-- Replaces the UHRI tagging of the recommendations of A/HRC/60/8 with HRCT's own classification
-- by Sustainable Development Goal and target. The UHRI tagging links by keyword in places (human
-- trafficking with target 15.7, on trafficking in protected species) and uses few targets, so each
-- recommendation was classified again from its official text, with the UHRI as a reference.
-- Criteria: docs/sdg.md. Review: data/sdg/hrct-review-spain-upr4.json, with a rationale per link.
-- The rows below are the output of `node scripts/sdg-review.mjs --sql`.
-- Safe to run again.

alter table public.commitment_sdgs
  add column if not exists rationale text,
  add column if not exists reviewed_at date;

create or replace view public.hrct_public_sdgs with (security_invoker = true) as
select c.public_id, s.goal, s.targets, s.source, s.source_published_at, s.rationale, s.reviewed_at
from public.commitment_sdgs s
join public.commitments c on c.id=s.commitment_id
where c.publication_status='published';

create temp table sdg_review (n int, goal smallint, targets text[], rationale text not null, primary key (n, goal));

-- (recommendation 50.n, goal, targets of that goal, why)

-- Links of the catalogue that the review does not keep.
delete from public.commitment_sdgs s
using public.commitments c
where c.id = s.commitment_id
  and c.public_id like 'ESP-UPR4-050.%'
  and not exists (select 1 from sdg_review r where c.public_id = 'ESP-UPR4-050.' || r.n and r.goal = s.goal);

select c.id, r.goal, r.targets, 'hrct', null, r.rationale, date '2026-10-05'
from sdg_review r
  join public.commitments c on c.public_id = 'ESP-UPR4-050.' || r.n
on conflict (commitment_id, goal) do update set targets = excluded.targets, source = excluded.source, source_published_at = excluded.source_published_at, rationale = excluded.rationale, reviewed_at = excluded.reviewed_at;

drop table sdg_review;
